public class InnerConfigurationSetEventDestinationFactory(Action<Humidifier.SMSVOICE.ConfigurationSetTypes.EventDestination> factoryAction = null) : SubResourceFactory<Humidifier.SMSVOICE.ConfigurationSetTypes.EventDestination>
{

    internal InnerConfigurationSetSnsDestinationFactory SnsDestinationFactory { get; set; }

    internal InnerConfigurationSetCloudWatchLogsDestinationFactory CloudWatchLogsDestinationFactory { get; set; }

    internal InnerConfigurationSetKinesisFirehoseDestinationFactory KinesisFirehoseDestinationFactory { get; set; }

    protected override Humidifier.SMSVOICE.ConfigurationSetTypes.EventDestination Create()
    {
        var eventDestinationResult = CreateEventDestination();
        factoryAction?.Invoke(eventDestinationResult);

        return eventDestinationResult;
    }

    private Humidifier.SMSVOICE.ConfigurationSetTypes.EventDestination CreateEventDestination()
    {
        var eventDestinationResult = new Humidifier.SMSVOICE.ConfigurationSetTypes.EventDestination();

        return eventDestinationResult;
    }
    public override void CreateChildren(Humidifier.SMSVOICE.ConfigurationSetTypes.EventDestination result)
    {
        base.CreateChildren(result);

        result.SnsDestination ??= SnsDestinationFactory?.Build();
        result.CloudWatchLogsDestination ??= CloudWatchLogsDestinationFactory?.Build();
        result.KinesisFirehoseDestination ??= KinesisFirehoseDestinationFactory?.Build();
    }

} // End Of Class

